        // Duplicates allowed in ALLOW_ALL
        final CSVFormat format = CSVFormat.Builder.create()
                .setHeader("A", "B", "A")
                .setDuplicateHeaderMode(DuplicateHeaderMode.ALLOW_ALL)
                .get();
        assertNotNull(format);
    }

    @Test
