        final CSVFormat f1 = CSVFormat.DEFAULT;
        final CSVFormat f2 = CSVFormat.DEFAULT;
        assertEquals(f1, f2);
        assertEquals(f1.hashCode(), f2.hashCode());

        final CSVFormat f3 = CSVFormat.Builder.create().setDelimiter(';').get();
        assertNotSame(f1, f3);
        assertFalse(f1.equals(f3));
    }

    @Test
