        assertEquals(original.getSkipHeaderRecord(), deserialized.getSkipHeaderRecord());
        assertEquals(original.getNullString(), deserialized.getNullString());
        assertEquals(original.getQuoteMode(), deserialized.getQuoteMode());
    }

