        private CSVRecord getNextRecord() {

            CSVRecord record = null;

            if (format.useRow(recordCount + 1)) {

                record = Uncheck.get(CSVParser.this::nextRecord);

                if (record != null) {

                    recordCount++;

                }

            }

            return record;

        }



