        int len = count;

        int pos = 0;



        while (pos < len && isTrimChar(charSequence, pos)) {

            pos++;

        }

        while (pos < len && isTrimChar(charSequence, len - 1)) {

            len--;

        }

        return pos > 0 || len < count ? charSequence.subSequence(pos, len) : charSequence;

