                        try (Reader reader = ((Clob) object).getCharacterStream()) {

                            print(reader);

                        }

                    } else if (object instanceof Blob) {

                        try (InputStream inputStream = ((Blob) object).getBinaryStream()) {

                            print(inputStream);

